    const stockMap=new Map(rets.map(x=>[x.d,x.r])),paired=dailyReturns((spyBars||[]).slice(-253)).filter(x=>stockMap.has(x.d)).map(x=>[stockMap.get(x.d),x.r]);let beta=null;if(paired.length>20){const am=paired.reduce((a,x)=>a+x[0],0)/paired.length,bm=paired.reduce((a,x)=>a+x[1],0)/paired.length,cov=paired.reduce((a,x)=>a+(x[0]-am)*(x[1]-bm),0)/(paired.length-1),variance=paired.reduce((a,x)=>a+(x[1]-bm)**2,0)/(paired.length-1);beta=variance?cov/variance:null;}
