    $('#smartMoves').innerHTML=`<div class="smart-table-head"><span>Titul</span><span>Investor / období</span><span>Změna kusů</span><span>Váha</span><span>Hodnota</span></div>${filtered.slice(0,80).map(({g,p})=>{const delta=ok(p.s)&&ok(p.ps)?(p.s-p.ps):null;const deltaPct=ok(delta)&&p.ps?delta/p.ps*100:null;return `<div class="smart-row"><button class="link-btn" data-open="${esc(p.t)}">${esc(p.t)}</button><span>${esc(g.label||g.fund||'Investor')}<small>${date(g.period)}</small></span><span class="${cls(delta)}">${p.ch==='new'?'Nová':p.ch==='out'?'Ukončená':ok(deltaPct)?pct(deltaPct):changeLabel(p.ch)}</span><span>${ok(p.w)?num(p.w,2)+' %':'—'}</span><b>${compact(p.v||p.pv)} $</b></div>`;}).join('')||'<div class="empty-state">Žádné aktuální pohyby neodpovídají filtru.</div>'}`;
