  function changeLabel(ch){return {new:'Nová pozice',add:'Navýšení',cut:'Snížení',out:'Ukončená pozice'}[ch]||'Změna';}

  function addCompare(){const input=$('#compareInput'),ticker=input.value.trim().toUpperCase().replace(/[^A-Z0-9.\-]/g,'');if(!ticker)return;if(!state.byTicker.has(ticker)){toast('Ticker není v aktuálním tržním snapshotu');return;}if(!state.compare.includes(ticker)){if(state.compare.length>=4){toast('Porovnat lze nejvýše 4 tituly');return;}state.compare.push(ticker);}input.value='';STORE.set('mt_compare_v1',state.compare);renderCompare();}
  function compareRisk(bars){
    const closes=(bars||[]).slice(-252).map(r=>Number(r?.[4])).filter(Number.isFinite);if(closes.length<3)return {vol:null,drawdown:null};
    const returns=[];for(let i=1;i<closes.length;i++)if(closes[i-1]>0&&closes[i]>0)returns.push(Math.log(closes[i]/closes[i-1]));
    const mean=returns.reduce((a,b)=>a+b,0)/returns.length,variance=returns.reduce((a,b)=>a+(b-mean)**2,0)/Math.max(1,returns.length-1);let peak=closes[0],maxDrawdown=0;for(const value of closes){peak=Math.max(peak,value);maxDrawdown=Math.min(maxDrawdown,value/peak-1);}
    return {vol:Math.sqrt(variance*252),drawdown:maxDrawdown};
  }
  async function renderCompare(){
    state.compare=state.compare.filter(t=>state.byTicker.has(t)).slice(0,4);STORE.set('mt_compare_v1',state.compare);$('#compareChips').innerHTML=state.compare.map(t=>`<span>${esc(t)}<button data-compare-remove="${esc(t)}" aria-label="Odebrat ${esc(t)}">×</button></span>`).join('');
    const stocks=state.compare.map(t=>state.byTicker.get(t)).filter(Boolean),box=$('#compareTable');if(stocks.length<2){box.innerHTML='<div class="empty-state">Přidej alespoň dva tickery pro porovnání.</div>';return;}
    const request=++state.compareRequest;box.innerHTML='<div class="skeleton h40 compare-loading"></div>';
    const details=await Promise.all(stocks.map(async s=>{const [fund,target,bars]=await Promise.all([data(`fundamentals/${s.ticker}.json`).catch(()=>null),data(`targets/${s.ticker}.json`).catch(()=>null),data(`bars/${s.ticker}.json`).catch(()=>[])]);return {fund,target:target?.none?null:target,risk:compareRisk(bars)};}));if(request!==state.compareRequest)return;
    const row=(label,fn,klass=()=>'',hint='')=>`<tr><th>${esc(label)}${hint?`<small>${esc(hint)}</small>`:''}</th>${stocks.map(s=>`<td class="${klass(s)}">${fn(s)}</td>`).join('')}</tr>`;
    const detail=s=>details[stocks.indexOf(s)]||{},valuation=s=>detail(s).fund?.valuation||{},ttm=s=>detail(s).fund?.ttm||{};
    box.innerHTML=`<table class="compare-table"><thead><tr><th>Metrika</th>${stocks.map(s=>`<th><button class="compare-symbol" data-open="${esc(s.ticker)}"><span class="mini-logo">${esc(s.ticker.slice(0,2))}</span><b>${esc(s.ticker)}</b><small>${esc(s.name||'')}</small></button></th>`).join('')}</tr></thead><tbody>
      ${row('Cena',s=>`<b>${money(s.price)}</b>`)}${row('Dnes',s=>`<b>${pct(s.change)}</b>`,s=>clsFor(s.ticker,s.change))}${row('Relativní objem',s=>`${rel(s.rel_volume)}<small>${esc(rvolHint(s))}</small>`,s=>Number(s.rel_volume)>=1.5?'up':'')}${row('52týdenní pozice',s=>`${num(yearPosition(s),0)} %`)}
      ${row('P/E (TTM)',s=>ok(valuation(s).pe_ttm)&&valuation(s).pe_ttm>0?`${num(valuation(s).pe_ttm,1)}×`:'—')}${row('P/S (TTM)',s=>ok(valuation(s).ps_ttm)?`${num(valuation(s).ps_ttm,1)}×`:'—')}${row('Růst tržeb',s=>ratioPct(valuation(s).revenue_growth_yoy),s=>cls(valuation(s).revenue_growth_yoy),'meziročně')}${row('Čistá marže',s=>ratioPct(valuation(s).net_margin),s=>cls(valuation(s).net_margin))}${row('FCF výnos',s=>ratioPct(valuation(s).fcf_yield),s=>cls(valuation(s).fcf_yield))}${row('Čistý dluh',s=>ok(valuation(s).net_debt)?`${compact(valuation(s).net_debt)} $`:'—',s=>cls(-(valuation(s).net_debt||0)))}
      ${row('Volatilita',s=>ratioPct(detail(s).risk?.vol),()=>'', 'anualizovaná')}${row('Max. propad',s=>ratioPct(detail(s).risk?.drawdown),s=>cls(detail(s).risk?.drawdown),'posledních 252 dní')}${row('Cíl analytiků',s=>{const t=detail(s).target,n=(t?.buy||0)+(t?.hold||0)+(t?.sell||0);return t&&ok(t.avg)?`${money(t.avg)}<small>${n} analytiků · ${pct((t.avg/s.price-1)*100)}</small>`:'—';})}
      ${row('Insider nákupy',s=>{const x=state.insiderSignals.get(s.ticker);return x?`${x.people} lidí · ${compact(x.value)} $`:'Žádné';})}${row('Aktuální 13F',s=>{const x=state.guruSignals.get(s.ticker);return x?`${x.new} nové · ${x.add} navýšené`:'Žádné';})}${row('MarketTrace skóre',s=>{const n=scoreStock(s);return `<span class="signal ${signalClass(n)}">${n}/100</span><small>${esc(scoreVerdict(s).split('–')[1]||'')}</small>`;})}
    </tbody></table>`;
  }
